// Package card connects a program that tessc compiled to the card. The
// program runs main as ordinary Go on the host; this package starts the
// program's card helper, a small C++ process that tessc writes and build.sh
// builds next to the program, and asks it to put files on the card and to run
// the workers of tt.Launch.
//
// Code generated by tessc installs it: tt.UseCard(card.New("program")).
// Programs do not use this package themselves.
//
// The helper is found next to the program's executable as
// <program>_card, or wherever the environment variable TESSERA_CARD says.
// It reads requests on its file descriptor 3 and answers on descriptor 4;
// its standard output goes to the program's standard error, so that
// tt-metal's log lines do not mix with the program's output.
package card

import (
	"encoding/binary"
	"fmt"
	"io"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"sync"

	"github.com/pavelgladyshev/tessera/tt"
)

// Requests, as in the helper (compiler/runtime/card_main.cpp).
const (
	opLoadBytes    = 1
	opOpenBytes    = 2
	opLoadDetector = 3
	opBytesRead    = 4
	opLaunch       = 5
	opClose        = 6
	opCores        = 7
	opPutLayer     = 8
	opPutMatrix    = 9
)

// Helper is a tt.Card that talks to the program's card helper. It starts the
// helper the first time the program uses the card.
type Helper struct {
	program string
	mu      sync.Mutex
	cmd     *exec.Cmd
	req     *os.File // the helper's descriptor 3
	ans     *os.File // the helper's descriptor 4
}

// New returns a Helper for the program of that name.
func New(program string) *Helper { return &Helper{program: program} }

func (h *Helper) path() string {
	if p := os.Getenv("TESSERA_CARD"); p != "" {
		return p
	}
	exe, err := os.Executable()
	if err != nil {
		fail("cannot find the program's executable: %v", err)
	}
	return filepath.Join(filepath.Dir(exe), h.program+"_card")
}

func (h *Helper) start() {
	if h.cmd != nil {
		return
	}
	path := h.path()
	reqR, reqW, err := os.Pipe()
	if err != nil {
		fail("%v", err)
	}
	ansR, ansW, err := os.Pipe()
	if err != nil {
		fail("%v", err)
	}
	cmd := exec.Command(path, h.program)
	cmd.Stdout = os.Stderr
	cmd.Stderr = os.Stderr
	cmd.ExtraFiles = []*os.File{reqR, ansW} // descriptors 3 and 4
	if err := cmd.Start(); err != nil {
		fail("cannot start the card helper: %v (build it with the program's build.sh, or set TESSERA_CARD)", err)
	}
	reqR.Close()
	ansW.Close()
	h.cmd, h.req, h.ans = cmd, reqW, ansR
}

// call sends one request and returns the answer's payload. If the helper
// stops instead (it prints why: a worker's panic, say), the program exits.
func (h *Helper) call(op uint32, payload []byte) []byte {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.start()
	msg := binary.LittleEndian.AppendUint32(nil, op)
	msg = binary.LittleEndian.AppendUint32(msg, uint32(len(payload)))
	msg = append(msg, payload...)
	var head [8]byte
	if _, err := h.req.Write(msg); err == nil {
		if _, err = io.ReadFull(h.ans, head[:]); err == nil {
			body := make([]byte, binary.LittleEndian.Uint32(head[4:]))
			if _, err = io.ReadFull(h.ans, body); err == nil {
				if binary.LittleEndian.Uint32(head[:]) != 0 {
					fail("%s", body)
				}
				return body
			}
		}
	}
	h.req.Close()
	if err := h.cmd.Wait(); err != nil {
		os.Exit(1) // the helper has said what went wrong
	}
	fail("the card helper stopped unexpectedly")
	return nil
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "tt/card: "+format+"\n", args...)
	os.Exit(1)
}

func appendString(b []byte, s string) []byte {
	b = binary.LittleEndian.AppendUint32(b, uint32(len(s)))
	return append(b, s...)
}

func (h *Helper) load(op uint32, path string) int {
	p := appendString(nil, filepath.Base(path))
	p = appendString(p, path)
	return int(binary.LittleEndian.Uint32(h.call(op, p)))
}

// LoadBytes implements tt.Card.
func (h *Helper) LoadBytes(path string) int { return h.load(opLoadBytes, path) }

// OpenBytes implements tt.Card.
func (h *Helper) OpenBytes(path string) int { return h.load(opOpenBytes, path) }

// LoadDetector implements tt.Card.
func (h *Helper) LoadDetector(path string) int { return h.load(opLoadDetector, path) }

// BytesRead implements tt.Card.
func (h *Helper) BytesRead(handle int) int {
	a := h.call(opBytesRead, binary.LittleEndian.AppendUint32(nil, uint32(handle)))
	return int(binary.LittleEndian.Uint64(a))
}

func appendFloats(b []byte, v []float32) []byte {
	b = binary.LittleEndian.AppendUint32(b, uint32(len(v)))
	for _, f := range v {
		b = binary.LittleEndian.AppendUint32(b, math.Float32bits(f))
	}
	return b
}

// PutLayer implements tt.Card.
func (h *Helper) PutLayer(in, out int, w, b []float32) int {
	p := binary.LittleEndian.AppendUint32(nil, uint32(in))
	p = binary.LittleEndian.AppendUint32(p, uint32(out))
	p = appendFloats(appendFloats(p, w), b)
	return int(binary.LittleEndian.Uint32(h.call(opPutLayer, p)))
}

// PutMatrix implements tt.Card.
func (h *Helper) PutMatrix(rows, cols int, v []float32) int {
	p := binary.LittleEndian.AppendUint32(nil, uint32(rows))
	p = binary.LittleEndian.AppendUint32(p, uint32(cols))
	return int(binary.LittleEndian.Uint32(h.call(opPutMatrix, appendFloats(p, v))))
}

// Cores implements tt.Card.
func (h *Helper) Cores() int { return int(binary.LittleEndian.Uint32(h.call(opCores, nil))) }

// Launch implements tt.Card.
func (h *Helper) Launch(k tt.Kernel, n, recordBytes int, args []tt.CardArg) []byte {
	p := appendString(nil, k.Name)
	for _, v := range []int{n, recordBytes, k.Capacity, k.Scratch, len(k.Positions)} {
		p = binary.LittleEndian.AppendUint32(p, uint32(v))
	}
	for _, pos := range k.Positions {
		p = appendString(p, pos.Where)
		p = appendString(p, pos.What)
	}
	p = binary.LittleEndian.AppendUint32(p, uint32(len(k.Tensors)))
	for _, tiles := range k.Tensors {
		p = binary.LittleEndian.AppendUint32(p, uint32(tiles))
	}
	p = binary.LittleEndian.AppendUint32(p, uint32(len(args)))
	for _, a := range args {
		p = binary.LittleEndian.AppendUint32(p, uint32(a.Kind))
		p = binary.LittleEndian.AppendUint64(p, uint64(a.Value))
		if a.Kind == tt.ArgString {
			p = appendString(p, a.Text)
		}
	}
	a := h.call(opLaunch, p)
	records := int(binary.LittleEndian.Uint32(a))
	if len(a)-4 != records*recordBytes {
		fail("the card helper sent %d bytes for %d records of %d bytes", len(a)-4, records, recordBytes)
	}
	return a[4:]
}

// Close implements tt.Card: the helper closes the card and exits.
func (h *Helper) Close() {
	if h.cmd == nil {
		return
	}
	h.call(opClose, nil)
	h.req.Close()
	h.cmd.Wait()
	h.cmd = nil
}
